head.b:skin:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#17221f;--paper:#f4f3ed;--lime:#d8f45e;--orange:#f47b4f;--muted:#66716d;--line:#d7dbd2}
*{box-sizing:border-box}html{background:var(--paper)}body{margin:0;color:var(--ink);background:var(--paper);font-family:Manrope,sans-serif}a{color:inherit;text-decoration:none}img{max-width:100%}
.wrap{width:min(1180px,calc(100% - 64px));margin:auto}.site-header{height:82px;padding:0 max(32px,calc((100% - 1180px)/2));display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:10px;font:700 20px Space Grotesk,sans-serif;letter-spacing:-.7px}.brand em{color:var(--orange);font-style:normal}.mark{display:grid;width:34px;height:34px;place-items:center;border-radius:50%;background:var(--lime);font-size:11px}.nav{display:flex;gap:25px;margin-left:auto;margin-right:35px;font-size:12px;font-weight:800}.nav a:hover,.more:hover{color:var(--orange)}.admin-link{border:1px solid var(--ink);border-radius:100px;padding:10px 15px;font-size:11px;font-weight:800}
.hero{position:relative;overflow:hidden;min-height:560px;padding:90px max(32px,calc((100% - 1180px)/2));color:var(--paper);background:var(--ink)}.hero:before{content:'';position:absolute;inset:0;opacity:.13;background-image:linear-gradient(115deg,transparent 49%,#fff 49.1% 49.4%,transparent 49.5%),linear-gradient(25deg,transparent 49%,#fff 49.1% 49.4%,transparent 49.5%);background-size:120px 120px}.hero-inner{position:relative;max-width:760px}.eyebrow,.kicker{color:var(--orange);font:10px 'DM Mono',monospace;letter-spacing:.7px;text-transform:uppercase}.hero .eyebrow{color:var(--lime)}.hero h1{margin:20px 0;font:600 clamp(62px,8vw,112px)/.87 'Space Grotesk',sans-serif;letter-spacing:-6px}.hero h1 em{color:var(--lime);font-style:normal}.hero-copy{max-width:420px;color:#b8c1b8;font-size:14px;line-height:1.7}.hero-search{display:flex;gap:10px;max-width:650px;margin-top:30px;padding:7px 8px 7px 17px;background:#26342f;border:1px solid #3e4d46;border-radius:5px}.hero-search input{flex:1;min-width:0;color:#fff;background:transparent;border:0;outline:0}.hero-search button,.button{border:0;padding:13px 18px;color:var(--ink);background:var(--lime);border-radius:4px;font-size:11px;font-weight:800;cursor:pointer}.hero-links{display:flex;gap:25px;margin-top:20px;color:#bbc5ba;font:10px 'DM Mono',monospace}.hero-links a:hover{color:var(--lime)}
.section{padding:85px 0}.section-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:28px}.section h2{margin:8px 0;font:600 43px/.95 'Space Grotesk',sans-serif;letter-spacing:-2px}.more{font-size:11px;font-weight:800}.post-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.post-card{overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:4px}.post-card img{width:100%;height:205px;display:block;object-fit:cover}.post-card-body{padding:18px}.post-card h3{margin:12px 0 16px;font:600 21px/1.1 'Space Grotesk',sans-serif}.post-card h3 a:hover{color:var(--orange)}.post-meta{display:flex;justify-content:space-between;color:var(--orange);font:9px 'DM Mono',monospace;text-transform:uppercase}.post-excerpt{color:var(--muted);font-size:12px;line-height:1.6}.dark-band{padding:85px 0;color:var(--paper);background:var(--ink)}.dark-band h2{color:var(--paper)}.label-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.label-tile{min-height:130px;display:flex;flex-direction:column;justify-content:space-between;padding:16px;color:#ced7ce;border:1px solid #405047;font:12px 'Space Grotesk',sans-serif}.label-tile:hover{border-color:var(--lime);background:#26342f}.label-number{color:var(--lime);font:21px 'DM Mono',monospace}.country-list{border-top:1px solid var(--line)}.country-row{display:grid;grid-template-columns:60px 1fr auto;gap:18px;padding:18px 8px;border-bottom:1px solid var(--line)}.country-row:hover{background:#e9eadf}.country-code{color:var(--orange);font:11px 'DM Mono',monospace}.country-row strong{font:600 18px 'Space Grotesk',sans-serif}.country-count{color:var(--muted);font:10px 'DM Mono',monospace}.spotlight{display:grid;grid-template-columns:1fr 1fr;background:#e3e8d9}.spotlight img{width:100%;height:100%;min-height:350px;object-fit:cover}.spotlight-copy{align-self:center;padding:55px 9%}.spotlight-copy h2{font-size:43px}.spotlight-copy p:not(.kicker){color:var(--muted);font-size:13px;line-height:1.7}.footer{padding:25px 0;color:#97a59a;background:var(--ink);font:10px 'DM Mono',monospace}.footer .wrap{display:flex;justify-content:space-between}
.content{padding:60px 0 100px}.content h1{font:600 60px 'Space Grotesk',sans-serif;letter-spacing:-3px}.content .post-body{max-width:760px;padding:28px 0;border-top:1px solid var(--line);font-size:15px;line-height:1.8}.content .post-body img{height:auto}.labels{display:flex;flex-wrap:wrap;gap:7px;margin:15px 0}.labels a{padding:6px 8px;color:var(--ink);background:var(--lime);font:9px 'DM Mono',monospace;text-transform:uppercase}
.widget{margin:0}.blog-pager,.feed-links,.post-footer,.date-header{display:none}.status-msg-wrap{padding:60px 0;text-align:center}.mobile-menu{display:none}
@media(max-width:850px){.wrap{width:calc(100% - 36px)}.site-header{padding:0 18px}.nav,.admin-link{display:none}.mobile-menu{display:block;border:0;background:transparent;font-size:22px}.hero{padding:70px 18px;min-height:610px}.hero h1{font-size:72px;letter-spacing:-4px}.hero-search{flex-wrap:wrap}.hero-search input{min-width:180px}.hero-search button{width:100%}.hero-links{flex-direction:column;gap:12px}.section{padding:60px 0}.section-head{align-items:start;flex-direction:column}.section h2{font-size:38px}.post-grid,.label-grid{grid-template-columns:1fr}.label-tile{min-height:95px}.country-row{grid-template-columns:42px 1fr}.country-count{display:none}.spotlight{grid-template-columns:1fr}.spotlight img{min-height:240px}.spotlight-copy{padding:40px 18px}.spotlight-copy h2{font-size:37px}.footer .wrap{align-items:start;flex-direction:column;gap:10px}.content h1{font-size:48px}}
